const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderStructuredText(text=''){const lines=String(text||'').replace(/\r\n?/g,'\n').split('\n');let html='',list=null;const close=()=>{if(list){html+=list==='ul'?'</ul>':'</ol>';list=null;}};for(const raw of lines){const line=raw.trim();if(!line){close();continue;}let m=line.match(/^##\s+(.+)$/);if(m){close();html+='<h4>'+esc(m[1])+'</h4>';continue;}m=line.match(/^[-•]\s+(.+)$/);if(m){if(list!=='ul'){close();html+='<ul>';list='ul';}html+='<li>'+esc(m[1])+'</li>';continue;}m=line.match(/^(\d+)\.\s+(.+)$/);if(m){if(list!=='ol'){close();html+='<ol>';list='ol';}html+='<li value="'+Number(m[1])+'">'+esc(m[2])+'</li>';continue;}close();html+='<p>'+esc(line)+'</p>';}close();return html||'<p class="muted">No structured text available.</p>';}
function renderTailorChanges(changes){if(!changes)return'';let h='';if(changes.profile)h+='<h4>PROFILE</h4><dl class="kv"><dt>Before</dt><dd>'+esc(changes.profile.before)+'</dd><dt>After</dt><dd>'+esc(changes.profile.after)+'</dd><dt>Why</dt><dd>'+esc(changes.profile.why)+'</dd></dl>';if(changes.experienceBullets?.length)h+='<h4>EXPERIENCE BULLETS</h4>'+changes.experienceBullets.map(x=>'<dl class="kv"><dt>Source</dt><dd>'+esc(x.source)+'</dd><dt>Before</dt><dd>'+esc(x.before)+'</dd><dt>After</dt><dd>'+esc(x.after)+'</dd><dt>Why</dt><dd>'+esc(x.why)+'</dd></dl>').join('');if(changes.keywordsSafelyIncorporated?.length)h+='<h4>Keywords safely incorporated</h4><div class="pill-list">'+changes.keywordsSafelyIncorporated.map(x=>badge(x,'ok')).join('')+'</div>';if(changes.keywordsNotIncorporated?.length)h+='<h4>Not incorporated — insufficient evidence</h4><div class="pill-list">'+changes.keywordsNotIncorporated.map(x=>badge(x,'warn')).join('')+'</div>';if(changes.template)h+='<h4>Template status</h4><pre class="jd">'+esc(JSON.stringify(changes.template,null,2))+'</pre>';if(changes.localWriter)h+='<h4>Local writer status</h4><pre class="jd">'+esc(JSON.stringify(changes.localWriter,null,2))+'</pre>';return h;}
function renderRecruiterIntelligence(r,j){const record=r.recruiterIntelligenceRecord||{},evidence=r.evidenceMatrix||r.evidence||j.requirements||[],actions=r.improvementInstructions||[],actionById=new Map(actions.filter(x=>x.requirementId).map(x=>[x.requirementId,x])),strengths=r.topStrengths||[],gaps=r.gaps||[],knockouts=r.knockoutGaps||[],noise=record.noise||[],scores=[['Recruiter qualification',r.recruiterQualificationScore??j.recruiter?.score],['Evidence match',r.evidenceMatchScore],['ATS discoverability',r.atsDiscoverabilityScore],['Interview defensibility',r.interviewDefensibilityScore],['Interview risk',r.interviewRiskScore]];let h=`<div class="grid2"><div><h4>Recruiter assessment</h4><p><b>${esc(j.recruiter?.verdict||'Not analysed')}</b> · ${Math.round(j.recruiter?.score??0)}%</p><p>${badge(record.version||'LEGACY ANALYSIS',record.version?'teal':'warn')} ${r.applicationPriority?badge(`Priority ${r.applicationPriority}`,'off'):''}</p><p class="muted">Recruiter qualification is the primary fit judgement. ATS discoverability is separate and cannot create unsupported evidence.</p></div><div><button class="btn primary" data-job-action="rematch">RE-RUN MATCH</button></div></div>`;h+=`<div class="grid2">${scores.filter(([,v])=>v!=null).map(([k,v])=>`<div class="note"><b>${esc(k)}</b><br>${Math.round(v)}%</div>`).join('')}</div>`;if(strengths.length)h+=`<h4>Top strengths</h4><ul>${strengths.map(x=>`<li>${esc(x.cleanText||x.text||x.requirement||'')} <span class="muted">${esc(x.evidenceGrade||'')}</span></li>`).join('')}</ul>`;if(gaps.length)h+=`<h4>Actual gaps</h4><ul>${gaps.map(x=>`<li>${esc(x.cleanText||x.text||x.requirement||'')} <span class="muted">${esc(x.evidenceGrade||'NO_EVIDENCE')}</span></li>`).join('')}</ul>`;if(knockouts.length)h+=`<div class="danger-note note"><b>Mandatory / knockout gaps</b><ul>${knockouts.map(x=>`<li>${esc(x.cleanText||x.text||x.reason||'')}</li>`).join('')}</ul></div>`;h+=`<h4>Requirement evidence matrix</h4><div class="matrix">${evidence.map(x=>{const a=actionById.get(x.id);return `<div class="req-row"><span>${badge(x.category||'REQ','off')}</span><span><b>${esc(x.cleanText||x.text||x.requirement||'')}</b><br><span class="muted">${esc(x.evidenceText||'No candidate evidence')} · ${esc(x.evidenceSourceType||'')}</span></span><span>${esc(x.evidenceGrade||x.evidence_grade||'')}<br>${a?badge(a.action,a.action==='GAP_DO_NOT_ADD'?'warn':'teal'):''}</span></div>`}).join('')||'<p class="muted">No requirement matrix available.</p>'}</div>`;if(actions.length)h+=`<h4>Controlled CV instructions</h4><ul>${actions.map(x=>`<li>${badge(x.action,x.action==='GAP_DO_NOT_ADD'?'warn':'off')} ${esc(x.requirement||'')} — ${esc(x.reason||'')}</li>`).join('')}</ul>`;if(noise.length)h+=`<details><summary>Excluded JD noise (${noise.length})</summary><ul>${noise.map(x=>`<li>${esc(x.cleanText||x.text||'')}</li>`).join('')}</ul></details>`;h+=`<p class="muted">${esc(record.scoreDisclaimer||'JCC scores are structured recruiter estimates, not scores from a commercial employer ATS.')}</p>`;return h;}
const state={route:'dashboard',summary:null,jobs:[],activeJobs:[],archivedJobs:[],graph:{nodes:[],links:[]},filters:{age:'any',role:'all',location:'all',match:'all',ats:'all',visa:'all',package:'all',q:''},page:1,pageSize:25,settingsTab:'profile',jobModal:null,jobTab:'overview',poll:null,queuePoll:null};
const api=async(url,opt={})=>{const r=await fetch(url,opt);const type=r.headers.get('content-type')||'';const data=type.includes('json')?await r.json():await r.text();if(!r.ok)throw new Error(data?.error||`HTTP ${r.status}`);return data};
const jsonOpt=(method,body)=>({method,headers:{'content-type':'application/json'},body:JSON.stringify(body)});
function toast(msg,err=false){const d=document.createElement('div');d.className='toast'+(err?' err':'');d.textContent=msg;$('#toastroot').append(d);setTimeout(()=>d.remove(),4200)}
function badge(text,cls='off'){return `<span class="badge b-${cls}">${esc(text)}</span>`}
function route(){const h=(location.hash||'#dashboard').slice(1);state.route=h||'dashboard';state.page=1;render().catch(e=>toast(e.message,true));}
const NAV=[
  ['WORK','dashboard','▦','Dashboard',null],['WORK','new','✦','New Opportunities','newJobs'],['WORK','strong','★','Strong Matches','strong'],['WORK','good','●','Good Matches','good'],['WORK','queue','→','Work Queue','queued'],['WORK','ready','✓','Ready to Apply','ready'],
  ['TRACK','applications','▣','Applications','applications'],['TRACK','followups','↗','Follow-ups','followups'],['TRACK','interviews','◈','Interviews','interviews'],['TRACK','contacts','◎','Contacts',null],['TRACK','archived','□','Archived','archived'],
  ['SYSTEM','graph','⌘','Knowledge Graph',null],['SYSTEM','history','◷','Search History',null],['SYSTEM','profile','♙','Candidate Profile',null],['SYSTEM','settings','⚙','Settings',null],['SYSTEM','logs','≡','System Logs',null]
];
function renderNav(){let last='';$('#nav').innerHTML=NAV.map(([sec,id,ico,label,count])=>{const heading=sec!==last?`<div class="nav-section">${sec}</div>`:'';last=sec;const n=count&&state.summary?state.summary[count]:null;const active=state.route===id||(id==='settings'&&state.route.startsWith('settings'));const href=id==='graph'?'/knowledge-graph':`#${id}`;return `${heading}<a href="${href}" class="${active?'active':''}" ${id==='graph'?'data-direct="1"':''}><span class="nav-label"><span class="ico">${ico}</span><span>${label}</span></span>${n!==null&&n!==undefined?`<span class="pill">${n}</span>`:''}</a>`}).join('')}
function pageMeta(title,sub=''){$('#pagetitle').textContent=title;$('#page-subtitle').textContent=sub||'';renderNav()}
async function refreshBase(){const [summary,activeJobs,archivedJobs,graph]=await Promise.all([api('/api/dashboard-v2'),api('/api/jobs?scope=active&limit=5000'),api('/api/jobs?scope=archived&limit=5000'),api('/api/knowledge-graph')]);state.summary=summary;state.activeJobs=activeJobs;state.archivedJobs=archivedJobs;state.jobs=[...activeJobs,...archivedJobs];state.graph=graph;$('#mode-pill').textContent=(summary.scheduler?.mode||'MANUAL').toUpperCase();$('#side-version').textContent='2.0.0-alpha.4';renderNav();updateRunUI(summary.scheduler,summary.lastRun)}
function updateRunUI(sched,run){const running=!!sched?.running;$('#runbtn').classList.toggle('hidden',running);$('#cancelbtn').classList.toggle('hidden',!running);$('#runstrip').classList.toggle('hidden',!running);if(!running)return;const st=run?.stats||{};$('#runbtn').textContent='SEARCHING';$('#runstrip').innerHTML=`<div class="metrics"><b>SEARCH RUNNING</b><span>Sources ${st.sourcesCompleted||0} / ${st.sourcesAttempted||0}</span><span>Inspected ${st.rawJobs||0}</span><span>Metadata ${st.metadataCandidates||0}</span><span>Deduped early ${st.dedupedBeforeHydration||0}</span><span>Recency rejects ${st.rejectedByRecency||0}</span><span>Role rejects ${st.rejectedByRole||0}</span><span>Location rejects ${st.rejectedByLocation||0}</span><span>Jev ${st.jevEvaluated||0}</span><span>Full JDs ${st.jdsRetrieved||0}</span><span>Accepted ${st.newCandidates||0}</span></div>`}
async function pollDiscovery(){clearInterval(state.poll);state.poll=setInterval(async()=>{try{const d=await api('/api/discovery/state');updateRunUI(d,d.latestRun);if(!d.running){clearInterval(state.poll);state.poll=null;await refreshBase();await render();}}catch{}},1000)}
async function runSearch(){try{await api('/api/discovery/run',{method:'POST'});toast('Discovery started');await pollDiscovery()}catch(e){toast(e.message,true)}}
async function cancelSearch(){try{await api('/api/discovery/cancel',{method:'POST'});toast('Cancel requested; completed source work will be kept.')}catch(e){toast(e.message,true)}}
function recency(job){const v=job.employer_published_at||job.source_published_at||job.posted_at;if(!v)return {label:'Date unverified',kind:'unverified',ts:null};const d=new Date(v);if(Number.isNaN(d.getTime()))return {label:String(v),kind:'reported',ts:null};const h=(Date.now()-d.getTime())/36e5;if(h<0)return {label:'Recent',kind:'recent',ts:d};if(h<1)return {label:'Just now',kind:'recent',ts:d};if(h<24)return {label:`${Math.floor(h)}h ago`,kind:'recent',ts:d};if(h<96)return {label:`${Math.floor(h/24)}d ago`,kind:'recent',ts:d};return {label:`${Math.floor(h/24)}d ago`,kind:'older',ts:d}}
function scoreClass(v){return v>=80?'strong':v>=70?'good':v>=60?'possible':'low'}
function matchText(j){const v=Math.round(j.recruiter_score??0);return j.recruiter_score==null?'—':`${v}%`}
function atsText(j){if(j.post_tailor?.afterAts!=null)return `${Math.round(j.post_tailor.beforeAts??j.ats_score??0)}% → ${Math.round(j.post_tailor.afterAts)}%`;return j.ats_score==null?'—':`${Math.round(j.ats_score)}%`}
function packageText(j){const s=j.application_status||j.status||'DISCOVERED';const map={READY_TO_APPLY:'Ready',APPLIED:'Applied',INTERVIEW:'Interview',TAILORING:'Tailoring',REVIEW:'Analysis',DISCOVERED:'Analysis',FOLLOW_UP_DUE:'Follow-up'};return map[s]||String(s).replaceAll('_',' ')}
function statusBadge(j){if(j.application_status==='READY_TO_APPLY')return badge('APPLY NOW','ok');if(j.recruiter_verdict==='STRONG MATCH')return badge('STRONG MATCH','strong');if(j.recruiter_verdict==='GOOD MATCH')return badge('GOOD MATCH','good');if(j.recruiter_verdict?.includes('POSSIBLE'))return badge('STRETCH','possible');return badge(j.status||'DISCOVERED',j.status==='DISCOVERED'?'new':'off')}
function jobFilter(base=state.jobs){let a=[...base],f=state.filters;const q=(f.q||'').toLowerCase();if(q)a=a.filter(j=>`${j.title} ${j.company} ${j.location_raw}`.toLowerCase().includes(q));if(f.age!=='any')a=a.filter(j=>{const r=recency(j);if(f.age==='24')return r.ts&&(Date.now()-r.ts)<864e5;if(f.age==='48')return r.ts&&(Date.now()-r.ts)<1728e5;if(f.age==='96')return r.ts&&(Date.now()-r.ts)<3456e5;if(f.age==='older')return r.kind==='older';if(f.age==='unverified')return r.kind==='unverified';return true});if(f.role!=='all')a=a.filter(j=>j.role_family===f.role);if(f.location!=='all')a=a.filter(j=>j.country_code===f.location||j.city===f.location);if(f.match!=='all')a=a.filter(j=>f.match==='strong'?j.recruiter_score>=80:f.match==='good'?j.recruiter_score>=70&&j.recruiter_score<80:f.match==='stretch'?j.recruiter_score>=60&&j.recruiter_score<70:j.recruiter_score<60);if(f.ats!=='all')a=a.filter(j=>f.ats==='tailored'?j.post_tailor!=null:j.post_tailor==null);if(f.visa!=='all')a=a.filter(j=>String(j.visa_status||'UNKNOWN')===f.visa);if(f.package!=='all')a=a.filter(j=>(j.application_status||j.status)===f.package);return a.sort((x,y)=>(Number(y.recruiter_score||0)-Number(x.recruiter_score||0))||((recency(y).ts?.getTime()||0)-(recency(x).ts?.getTime()||0)))}
function contextJobs(routeId=state.route){let a=routeId==='archived'?state.archivedJobs:state.activeJobs;if(routeId==='new')a=a.filter(j=>j.status==='DISCOVERED');if(routeId==='strong')a=a.filter(j=>j.recruiter_score>=80);if(routeId==='good')a=a.filter(j=>j.recruiter_score>=70&&j.recruiter_score<80);if(routeId==='ready')a=a.filter(j=>j.application_status==='READY_TO_APPLY');return jobFilter(a)}
function filtersHtml(){const roles=[...new Set(state.jobs.map(j=>j.role_family).filter(Boolean))].sort();const locs=[...new Map(state.jobs.map(j=>[j.country_code||j.city||j.location_raw,[j.country_code||j.city||j.location_raw,j.country||j.city||j.location_raw]])).values()];return `<div class="card filters-card"><div class="filters"><label>Posting age<select data-filter="age"><option value="any">Any</option><option value="24">Last 24 hours</option><option value="48">Last 48 hours</option><option value="96">Last 96 hours</option><option value="older">Older active</option><option value="unverified">Date unverified</option></select></label><label>Role family<select data-filter="role"><option value="all">All</option>${roles.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Country / Location<select data-filter="location"><option value="all">All</option>${locs.map(([v,l])=>`<option value="${esc(v)}">${esc(l)}</option>`).join('')}</select></label><label>Professional match<select data-filter="match"><option value="all">All</option><option value="strong">Strong 80%+</option><option value="good">Good 70–79%</option><option value="stretch">Stretch 60–69%</option><option value="weak">Weak &lt;60%</option></select></label><label>ATS<select data-filter="ats"><option value="all">All</option><option value="tailored">Tailored</option><option value="not-tailored">Not tailored</option></select></label><label>Visa / Sponsorship<select data-filter="visa"><option value="all">All</option><option value="CONFIRMED_SPONSOR">Confirmed sponsor</option><option value="SPONSORSHIP_INDICATED">Sponsorship indicated</option><option value="UNKNOWN">Unknown</option><option value="POTENTIAL_ISSUE">Potential issue</option><option value="NEEDS_REVIEW">Needs review</option></select></label><label>Package<select data-filter="package"><option value="all">All</option><option value="READY_TO_APPLY">Ready to apply</option><option value="APPLIED">Applied</option><option value="INTERVIEW">Interview</option></select></label></div><div class="filters-actions"><button class="btn sm" id="clearfilters">Clear filters</button></div></div>`}
function jobsTable(jobs){if(!jobs.length)return `<div class="card"><div class="empty"><h3>No jobs in this view</h3><p>Run discovery or change the filters.</p><button class="btn go" data-run-search>RUN SEARCH NOW</button></div></div>`;const pages=Math.ceil(jobs.length/state.pageSize);state.page=Math.min(state.page,pages);const start=(state.page-1)*state.pageSize,rows=jobs.slice(start,start+state.pageSize);return `<div class="card"><div class="tablewrap"><table><thead><tr><th>Status</th><th>Job ID</th><th>Role / Company</th><th>Location</th><th>Posted</th><th>Professional Match</th><th>ATS</th><th>Visa</th><th>Package</th><th>Actions</th></tr></thead><tbody>${rows.map(j=>{const r=recency(j),sendable=!['ARCHIVED','EXPIRED','QUEUED_FOR_WORK'].includes(j.status),deletable=j.status!=='ARCHIVED',needsOverride=!j.application_override_at&&(!['ROLE_MATCH','ROLE_RELATED'].includes(j.role_classification)||!['STRONG MATCH','GOOD MATCH'].includes(j.recruiter_verdict));return `<tr><td>${statusBadge(j)}</td><td class="mono">JOB-${String(j.id).padStart(4,'0')}</td><td class="role"><b>${esc(j.title)}</b><small>${esc(j.company)}</small></td><td>${esc(j.location_raw||[j.city,j.country].filter(Boolean).join(', ')||'—')}</td><td>${r.kind==='unverified'?badge(r.label,'warn'):esc(r.label)}</td><td><span class="score ${scoreClass(j.recruiter_score)}">${matchText(j)}</span><br><span class="small muted">${esc(j.recruiter_verdict||'Not analysed')}</span>${j.application_override_at?'<br>'+badge('USER OVERRIDE','warn'):''}</td><td class="nowrap">${esc(atsText(j))}</td><td>${badge(String(j.visa_status||'UNKNOWN').replaceAll('_',' '),j.visa_status==='CONFIRMED_SPONSOR'?'ok':j.visa_status==='POTENTIAL_ISSUE'?'warn':'off')}</td><td>${badge(packageText(j),j.application_status==='READY_TO_APPLY'?'teal':j.application_status==='APPLIED'?'ok':'off')}</td><td><div class="actions"><button class="btn sm" data-view-job="${j.id}">VIEW</button>${needsOverride?`<button class="btn sm" data-override-job="${j.id}">OVERRIDE</button>`:''}${sendable?`<button class="btn sm primary" data-send-job="${j.id}">SEND</button>`:''}<button class="btn sm" data-open-app="${j.id}">OPEN ↗</button>${deletable?`<button class="btn sm" data-delete-job="${j.id}">DELETE</button>`:''}</div></td></tr>`}).join('')}</tbody></table></div>${pages>1?`<div class="pager"><span class="muted">${start+1}-${Math.min(start+state.pageSize,jobs.length)} of ${jobs.length}</span><button class="btn sm" data-page="${state.page-1}" ${state.page===1?'disabled':''}>Previous</button><span>${state.page} / ${pages}</span><button class="btn sm" data-page="${state.page+1}" ${state.page===pages?'disabled':''}>Next</button></div>`:''}</div>`}
function graphCard(){return `<div class="card"><div class="body graph-card"><div><strong>Knowledge Graph</strong><span>Live system map · jobs, applications, CVs, sources, skills and interviews</span></div><div class="actions"><span class="graph-count">${state.graph.nodes?.length||0} nodes · ${state.graph.links?.length||0} links</span><span class="live-dot">LIVE</span><a class="btn sm primary" href="/knowledge-graph">OPEN 3D GRAPH</a></div></div></div>`}
function dashboard(){const s=state.summary||{};pageMeta('Dashboard','What requires your attention today');const last=s.lastRun?.finished_at||s.lastRun?.started_at;const hero=`<div class="hero-status"><div class="statusline"><div class="item">Last Discovery<b>${last?new Date(last+'Z').toLocaleString():'Not run yet'}</b></div><div class="item">Active CV<b>${esc(s.activeCv?.versionLabel||'No master CV')}</b></div><div class="item">Jobs<b>${s.activeJobs||0} active · ${s.archived||0} archived · ${s.totalStored||0} stored</b></div><div class="item">Mode<b>${esc(s.scheduler?.mode||'MANUAL')}</b></div></div><div class="source-summary"><span class="health-dot ok"></span>${s.sources?.healthy||0} healthy · <span class="health-dot warn"></span>${s.sources?.degraded||0} attention · ${s.sources?.manual||0} manual</div></div>`;const kpis=[['newJobs','New Jobs','Confirmed / discovered','blue','new'],['strong','Strong Matches','80% and above','green','strong'],['good','Good Matches','70–79%','blue','good'],['queued','Work Queue','Selected for production','blue','queue'],['ready','Ready to Apply','Accepted final package','teal','ready'],['applied','Applied','Recorded by you','violet','applications'],['followups','Follow-ups Due','Action required','amber','followups'],['interviews','Interviews','Preparation linked','green','interviews']];return hero+`<div class="kpis">${kpis.map(([key,l,sub,c,r])=>`<div class="kpi c-${c} clickable" data-route="${r}"><div class="n">${s[key]||0}</div><div class="l">${l}</div><div class="s">${sub}</div></div>`).join('')}</div>`+graphCard()+filtersHtml()+jobsTable(jobFilter(state.activeJobs))}
function jobsPage(kind){const names={new:['New Opportunities','Recently discovered roles'],strong:['Strong Matches','Professional match 80% and above'],good:['Good Matches','Professional match 70–79%'],ready:['Ready to Apply','Packages prepared for your review'],archived:['Archived','Closed or archived opportunities']};pageMeta(...names[kind]);return filtersHtml()+jobsTable(contextJobs(kind))}
async function queuePage(){pageMeta('Work Queue','Jobs selected for application production');const rows=await api('/api/work-queue');const actions=r=>`<button class="btn sm" data-view-job="${r.job_id}">VIEW</button>${r.state==='QUEUED'?`<button class="btn sm primary" data-process-queue="${r.id}">PROCESS</button>`:''}${r.state==='READY_FOR_REVIEW'?`<button class="btn sm" data-review-queue="${r.id}" data-job-id="${r.job_id}">REVIEW</button><button class="btn sm" data-retry-queue="${r.id}" title="Create a fresh package from the current JD and Master CV">REGENERATE</button>${r.reviewed_at?`<button class="btn sm primary" data-approve-queue="${r.id}">APPROVE</button>`:''}`:''}${r.state==='NEEDS_CONFIRMATION'?`<button class="btn sm" data-open-queue-package="${r.job_id}">REVIEW BLOCKERS</button><button class="btn sm primary" data-resolve-queue="${r.id}">CONFIRM FACTS</button><button class="btn sm" data-retry-queue="${r.id}">RETRY</button>`:''}${r.state==='FAILED'?`<button class="btn sm primary" data-retry-queue="${r.id}">RETRY</button>`:''}`;return simpleTable(rows,['state','job_id','company','role','location','recruiter_verdict','last_error','queued_at'],actions,'No jobs are queued. Use SEND on a suitable job to create an isolated handoff package.')}
async function listPage(kind){if(kind==='applications'){pageMeta('Applications','Your manually controlled application pipeline');const rows=await api('/api/applications');return simpleTable(rows,['status','company','title','location_raw','applied_at'],r=>`<button class="btn sm" data-view-job="${r.job_id}">VIEW</button>`,'No applications yet. Create a job application package from a job workspace.')}if(kind==='followups'){pageMeta('Follow-ups','Due dates and application follow-up');const rows=await api('/api/followups');return simpleTable(rows,['status','due_at','company','title','kind'],r=>`<button class="btn sm" data-view-job="${r.job_id}">JOB</button>`,'No follow-ups are due.')}if(kind==='interviews'){pageMeta('Interviews','Exact submitted CV + JD context is linked to every interview');const rows=await api('/api/interviews');return simpleTable(rows,['status','scheduled_at','company','title','stage','mode'],r=>`<button class="btn sm" data-view-job="${r.job_id}">PREP</button>`,'No interviews yet. Interview preparation will appear when applications progress.')}if(kind==='contacts'){pageMeta('Contacts','Public recruiter, hiring manager and referral contacts');const rows=await api('/api/contacts');return simpleTable(rows,['name','company','role','relationship','job_count'],null,'No contacts yet. Contacts linked to viable jobs will appear here.')}}
function simpleTable(rows,cols,actions,empty){if(!rows.length)return `<div class="card"><div class="empty"><h3>${esc(empty)}</h3></div></div>`;return `<div class="card"><div class="tablewrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c.replaceAll('_',' '))}</th>`).join('')}${actions?'<th>Actions</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${esc(r[c]??'—')}</td>`).join('')}${actions?`<td>${actions(r)}</td>`:''}</tr>`).join('')}</tbody></table></div></div>`}
async function historyPage(){pageMeta('Search History','Auditable discovery runs and source attempts');const runs=await api('/api/discovery/runs');if(!runs.length)return `<div class="card"><div class="empty"><h3>No discovery runs yet</h3><button class="btn go" data-run-search>RUN FIRST SEARCH</button></div></div>`;return `<div class="card"><div class="tablewrap"><table><thead><tr><th>Run</th><th>Started</th><th>Mode</th><th>Status</th><th>Sources</th><th>Listings</th><th>Relevant</th><th>New Jobs</th><th>Errors</th><th></th></tr></thead><tbody>${runs.map(r=>`<tr><td>#${r.id}</td><td>${esc(r.started_at)}</td><td>${esc(r.mode)}</td><td>${badge(r.status,r.status==='COMPLETE'?'ok':r.status==='RUNNING'?'new':'warn')}</td><td>${r.stats?.sourcesCompleted||0}/${r.stats?.sourcesAttempted||0}</td><td>${r.stats?.rawJobs||0}</td><td>${r.stats?.roleRelevant||0}</td><td>${r.stats?.newCandidates||0}</td><td>${r.stats?.errors?.length||0}</td><td><button class="btn sm" data-run-detail="${r.id}">VIEW</button></td></tr>`).join('')}</tbody></table></div></div>`}
async function profilePage(){pageMeta('Candidate Profile','Master CV and candidate evidence');return settingsPage('profile',true)}
const SETTINGS=[['profile','Profile & Master CV'],['roles','Target Roles'],['locations','Target Locations'],['sources','Discovery & Sources'],['automation','Automation'],['applications','Application Preferences'],['knowledge','Knowledge / Obsidian'],['backup','Backup & Restore'],['system','System / Diagnostics']];
async function settingsPage(tab=state.settingsTab,standalone=false){state.settingsTab=tab;pageMeta(standalone?'Candidate Profile':'Settings',standalone?'Master CV and evidence':'Job discovery, workflow and local system preferences');const nav=standalone?'':`<div class="settings-nav">${SETTINGS.map(([id,l])=>`<button data-setting-tab="${id}" class="${tab===id?'active':''}">${l}</button>`).join('')}</div>`;return `<div class="settings-layout ${standalone?'profile-only':''}">${nav}<div class="settings-pane">${await settingPane(tab)}</div></div>`}
async function settingPane(tab){if(tab==='profile'){const [cv,tpl]=await Promise.all([api('/api/cv'),api('/api/cv/template')]);const a=cv.active,t=tpl.template,docx=cv.versions.filter(v=>/\.docx$/i.test(v.original_filename||''));return `<div class="card"><h3>Active Master Content</h3><div class="body">${a?`<dl class="kv"><dt>Filename</dt><dd>${esc(a.original_filename)}</dd><dt>Version</dt><dd>${esc(a.version_label)}</dd><dt>Imported</dt><dd>${esc(a.created_at)}</dd><dt>SHA-256</dt><dd class="mono">${esc(a.sha256)}</dd><dt>Status</dt><dd>${badge('ACTIVE MASTER CONTENT','ok')}</dd></dl>`:`<div class="empty"><h3>No Active Master Content</h3><p>Import a master CV before recruiter and ATS analysis. Existing master files are never overwritten.</p></div>`}<div style="margin-top:14px"><input type="file" id="cvfile" accept=".pdf,.docx,.txt,.md"> <button class="btn primary" id="importcv">${a?'IMPORT NEW MASTER VERSION':'IMPORT MASTER CV'}</button></div></div></div><div class="card" style="margin-top:14px"><h3>Formatting Template</h3><div class="body">${t?`<dl class="kv"><dt>DOCX</dt><dd>${esc(t.filename)}</dd><dt>Version</dt><dd>${esc(t.versionLabel)}</dd><dt>SHA-256</dt><dd class="mono">${esc(t.sha256)}</dd><dt>Status</dt><dd>${badge('FORMAT TEMPLATE','teal')}</dd></dl>`:'<p class="muted">No Master DOCX template selected. Tailored DOCX/PDF output will report ATS-renderer fallback truthfully.</p>'}${docx.length?`<div class="actions">${docx.map(v=>`<button class="btn sm" data-template-cv="${v.id}">USE ${esc(v.original_filename)} AS TEMPLATE</button>`).join('')}</div>`:'<p class="muted small">Import a DOCX Master version if you want its formatting used independently from the active evidence content.</p>'}</div></div>`}
if(tab==='roles'){const rows=await api('/api/roles');const families=[...new Set(rows.map(r=>r.family))];return `<div class="card"><h3>Target Roles <span class="small muted">${rows.filter(x=>x.enabled).length} enabled</span></h3><div class="body"><div class="inline-form"><label class="formlabel">Family<input id="rolefamily" placeholder="TRADING"></label><label class="formlabel">Role phrase<input id="rolephrase" placeholder="e.g. Options Trader"></label><button class="btn primary" id="addrole">ADD ROLE</button></div>${families.map(f=>`<div style="margin-top:15px"><b>${esc(f)}</b>${rows.filter(r=>r.family===f).map(r=>`<div class="setting-row"><div class="meta"><span>${esc(r.phrase)}</span></div><label class="toggle"><input type="checkbox" data-role-toggle="${r.id}" ${r.enabled?'checked':''}> Enabled</label></div>`).join('')}</div>`).join('')}</div></div>`}
if(tab==='locations'){const rows=await api('/api/locations');return `<div class="card"><h3>Global Target Locations <span class="small muted">${rows.filter(x=>x.enabled).length} enabled · ${rows.length} unique</span></h3><div class="body"><p class="muted small">Enter a city, country, or city + country. ISO country aliases are normalized locally; ambiguous free-form cities are kept without inventing a country.</p><div class="inline-form"><label class="formlabel">Location<input id="locationlabel" placeholder="e.g. Singapore or Toronto, Canada"></label><button class="btn primary" id="addlocation">ADD LOCATION</button></div><div style="margin-top:12px">${rows.map(r=>`<div class="setting-row"><div class="meta"><b>${esc(r.display_label||[r.city,r.region,r.country].filter(Boolean).join(', '))}</b><small>${esc(r.normalized_key||'')} · ${esc(r.origin||'')}</small></div><label class="toggle"><input type="checkbox" data-location-toggle="${r.id}" ${r.enabled?'checked':''}> Enabled</label></div>`).join('')}</div></div></div>`}
if(tab==='sources'){const rows=await api('/api/source-manager');const hc=k=>rows.filter(r=>r.health===k).length;return `<div class="card"><h3>Auto-managed Source Registry</h3><div class="body"><div class="source-health-grid"><div class="mini-stat"><b>${rows.filter(r=>r.enabled).length}</b><span>Active sources</span></div><div class="mini-stat"><b>${hc('HEALTHY')+hc('READY')}</b><span>Healthy / ready</span></div><div class="mini-stat"><b>${hc('DEGRADED')+hc('UNTESTED')}</b><span>Need attention</span></div><div class="mini-stat"><b>${rows.filter(r=>r.ownership==='AUTO_DISCOVERED').length}</b><span>Auto-discovered</span></div></div><div class="tablewrap" style="margin-top:12px"><table><thead><tr><th>Source</th><th>Type</th><th>Adapter</th><th>Ownership</th><th>Health</th><th>Last success</th><th>Jobs</th><th>Enabled</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.name)}</b><br><small class="muted">${esc(r.base_url||'')}</small></td><td>${esc(r.kind)}</td><td>${esc(r.adapter||'auto')}</td><td>${badge(r.ownership||'USER_ADDED',r.ownership==='SYSTEM'?'good':r.ownership==='AUTO_DISCOVERED'?'teal':'off')}</td><td>${badge(r.health,r.health==='HEALTHY'||r.health==='READY'?'ok':r.health==='MANUAL_ONLY'?'warn':'off')}</td><td>${esc(r.last_success||'—')}</td><td>${r.jobs_seen||r.jobs_found||0}</td><td><input type="checkbox" data-source-toggle="${r.id}" ${r.enabled?'checked':''}></td></tr>`).join('')}</tbody></table></div><details style="margin-top:13px"><summary>Advanced: add a public careers / ATS source</summary><div class="inline-form"><label class="formlabel">Source name<input id="sourcename"></label><label class="formlabel">Public URL<input id="sourceurl" placeholder="https://company.example/careers"></label><button id="addsource" class="btn primary">ADD SOURCE</button></div></details></div></div>`}
if(tab==='automation'){const s=state.summary?.scheduler||{},jev=await api('/api/jev/status');return `<div class="card"><h3>Discovery Automation</h3><div class="body"><div class="setting-row"><div class="meta"><b>Manual</b><small>Discovery only runs when you click RUN SEARCH NOW.</small></div><button class="btn ${s.mode==='MANUAL'?'primary':''}" data-mode="MANUAL">USE MANUAL</button></div><div class="setting-row"><div class="meta"><b>Auto every 3 hours</b><small>Runs only while local JCC is running. It never applies or sends messages.</small></div><button class="btn ${s.mode==='AUTO'?'primary':''}" data-mode="AUTO">USE AUTO 3H</button></div><div class="setting-row"><div class="meta"><b>Optional Jev pre-classifier</b><small>${jev.available?'Available at the configured external path. Used only for ambiguous post-filter candidates.':'Unavailable on this machine. Discovery continues without it.'}</small></div><button class="btn ${jev.enabled?'primary':''}" data-jev-toggle="${jev.enabled?'0':'1'}" ${!jev.available?'disabled':''}>${jev.enabled?'DISABLE':'ENABLE'}</button></div></div></div>`}
if(tab==='applications'){const f=await api('/api/profile/application-facts');return `<div class="card"><h3>Application Preferences</h3><div class="body"><div class="success-note note"><b>Manual application control is locked.</b><br>JCC may discover, analyse, tailor and prepare. You remain responsible for the final external submission and explicit MARK APPLIED action.</div><p class="muted">Record current facts explicitly. Saving this form is evidence; clicking CONFIRM / RESOLVE alone is not.</p><div class="grid2">${[['workAuthorisation','Work authorisation'],['sponsorship','Sponsorship'],['salary','Salary expectations'],['noticePeriod','Notice period'],['relocation','Relocation'],['startDate','Start date']].map(([k,l])=>`<label class="formlabel">${l}<input data-application-fact="${k}" value="${esc(f[k]||'')}"></label>`).join('')}</div><button class="btn primary" id="saveapplicationfacts">SAVE CURRENT CONFIRMATIONS</button></div></div>`;}
if(tab==='knowledge')return `<div class="card"><h3>Knowledge / Obsidian</h3><div class="body">${graphCard()}<p>The JCC-Knowledge vault remains the durable Markdown/wikilink layer. The built-in graph and optional Obsidian graph represent the same knowledge relationships.</p><div class="actions"><a href="/knowledge-graph" class="btn primary">OPEN LIVE 3D GRAPH</a><button class="btn" id="openobsidian">OPEN OBSIDIAN VAULT</button></div></div></div>`;
if(tab==='backup'){const b=await api('/api/system/backups');return `<div class="card"><h3>Backup & Restore</h3><div class="body"><p>Backups include a consistent SQLite snapshot and the knowledge vault; secrets/browser state are excluded.</p><button class="btn primary" id="runbackup">CREATE BACKUP NOW</button><h4>Recent backups</h4>${b.backups.length?`<ul>${b.backups.map(x=>`<li class="mono">${esc(x)}</li>`).join('')}</ul>`:'<p class="muted">No backups yet.</p>'}<div class="note">Restore remains a stopped-JCC maintenance operation so the running database cannot be replaced underneath the server.</div></div></div>`;}
if(tab==='system'){return `<div class="card"><h3>System / Diagnostics</h3><div class="body"><p>Full Doctor is intentionally run only here; the normal runtime health endpoint stays lightweight.</p><button class="btn primary" id="rundoctor">RUN DOCTOR</button><div id="doctorout" style="margin-top:12px"></div></div></div>`}return ''}
async function logsPage(){pageMeta('System Logs','Local runtime log · secrets are never shown intentionally');const x=await api('/api/system/logs?limit=400');return `<div class="card"><h3>Runtime Log <button class="btn sm" id="refreshlogs">Refresh</button></h3><div class="body"><div class="logbox">${esc(x.lines.join('\n')||'No runtime log entries yet.')}</div></div></div>`}
function openModal(title,body,foot='',wide=false){$('#modalroot').innerHTML=`<div class="modal-bg"><div class="modal ${wide?'wide':''}"><h3>${esc(title)}<button class="iconbtn" data-close-modal>✕</button></h3><div class="mbody">${body}</div>${foot?`<div class="mfoot">${foot}</div>`:''}</div></div>`}
function closeModal(){$('#modalroot').innerHTML='';state.jobModal=null}
function importJobModal(){openModal('Import Job',`<div class="f2"><label class="formlabel">Company<input id="ijcompany"></label><label class="formlabel">Role title<input id="ijtitle"></label></div><label class="formlabel">Location<input id="ijlocation"></label><label class="formlabel">Job URL<input id="ijurl"></label><label class="formlabel">Full job description<textarea id="ijjd" rows="12"></textarea></label>`,`<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="saveimportjob">IMPORT & ANALYSE</button>`)}
async function openJob(id,tab='overview'){state.jobModal=await api(`/api/jobs/${id}`);state.jobTab=tab;renderJobModal()}
function renderJobModal(){const j=state.jobModal;if(!j)return;const tabs=['overview','jd','match','ats','cv','application','contacts','interview','history'];let body=`<div class="tabs">${tabs.map(t=>`<button data-job-tab="${t}" class="${state.jobTab===t?'active':''}">${t.toUpperCase()}</button>`).join('')}</div>`;const r=j.recruiter?.payload||{},a=j.ats?.payload||{},pt=j.postTailor?.payload||{},art=j.preparedArtifacts||{};
if(state.jobTab==='overview')body+=`<div class="actions"><button class="btn primary" data-job-action="send">SEND TO WORK QUEUE</button>${j.application_override_at?'':`<button class="btn" data-job-action="override">OVERRIDE MATCH DECISION</button>`}<button class="btn" data-job-action="open-application">OPEN APPLICATION PAGE</button><button class="btn" data-job-action="delete">DELETE JOB</button></div><dl class="kv"><dt>Company</dt><dd>${esc(j.company)}</dd><dt>Role</dt><dd>${esc(j.title)}</dd><dt>Location</dt><dd>${esc(j.location_raw)}</dd><dt>Posted</dt><dd>${esc(recency(j).label)}</dd><dt>Source</dt><dd><a href="${esc(j.source_url)}" target="_blank">${esc(j.source_url||'—')}</a></dd><dt>Official / Apply URL</dt><dd><a href="${esc(j.application_url||j.canonical_job_url)}" target="_blank">Open ↗</a></dd><dt>Recruiter Match</dt><dd>${badge(`${Math.round(j.recruiter?.score??0)}% · ${j.recruiter?.verdict||'Not analysed'}`,scoreClass(j.recruiter?.score))}</dd><dt>Manual Override</dt><dd>${j.application_override_at?badge('USER APPROVED','warn')+' '+esc(j.application_override_reason||''): 'Not used'}</dd><dt>ATS Exact</dt><dd>${j.ats?.score==null?'—':Math.round(j.ats.score)+'%'}</dd><dt>Status</dt><dd>${badge(j.application?.status||j.status,'off')}</dd><dt>Work Queue</dt><dd>${j.workQueue?badge(`${j.workQueue.state} · v${j.workQueue.queue_version}`,'teal'):'Not queued'}</dd></dl>`;
if(state.jobTab==='jd')body+=`<div class="actions"><button class="btn" data-job-action="reclean-jd">RE-CLEAN STORED JD</button></div><div class="jd structured-jd">${renderStructuredText(j.jd?.jd_clean||'Full JD has not been retrieved yet.')}</div>`;
if(state.jobTab==='match')body+=renderRecruiterIntelligence(r,j);
if(state.jobTab==='ats'){const present=a.exactPhraseMatches||[],missing=a.missingWording||[],actions=a.actions||[];body+=`<h4>ATS Exact · secondary metric</h4><p>${j.ats?.score==null?'Not analysed':`Exact supported-term coverage: <b>${Math.round(j.ats.score)}%</b>`}</p><div class="grid2"><div><h4>Keywords already present</h4>${present.length?`<div class="pill-list">${present.map(x=>badge(x,'ok')).join('')}</div>`:'<p class="muted">No exact supported terms recorded.</p>'}</div><div><h4>Actual missing wording</h4>${missing.length?`<div class="pill-list">${missing.map(x=>badge(x,'warn')).join('')}</div>`:'<p class="muted">No missing exact terms recorded.</p>'}</div></div><h4>Safe wording improvements</h4>${actions.length?`<ul>${actions.map(x=>`<li><b>${esc(x.phrase)}</b> — ${esc(x.action)}. ${esc(x.note||'')}</li>`).join('')}</ul>`:'<p class="muted">No ATS wording action proposed.</p>'}<p class="muted">Unsupported keywords are never inserted merely to raise this score; every proposed term still requires evidence-led support.</p>`;}
if(state.jobTab==='cv'){const change=j.cvVersions?.[0]?.change_log||'',changes=pt.structuredChanges||null;body+=`<div class="actions"><button class="btn primary" data-job-action="tailor">TAILOR CV</button><button class="btn" data-job-action="verify">VERIFY LATEST TAILORED</button></div>${j.postTailor?`<div class="success-note note" style="margin-top:12px"><b>Post-tailor verification</b><br>Recruiter ${pt.beforeRecruiter??'—'} → ${pt.afterRecruiter??j.postTailor.score??'—'} · ATS ${pt.beforeAts??'—'} → ${pt.afterAts??'—'} · Integrity ${esc(pt.integrity||j.postTailor.verdict||'recorded')}${Array.isArray(pt.unsupportedClaims)&&pt.unsupportedClaims.length?`<br><b>Unsupported claims:</b> ${pt.unsupportedClaims.map(x=>esc(x.reason||x.code||String(x))).join('; ')}`:' · Unsupported claims: 0'}<br>Template ${pt.templatePreserved?'preserved':'fallback'} · PDF ${pt.pdfTemplatePreserved?'template-preserved':'fallback'} · Renderer ${esc(pt.renderer||'—')}</div>`:''}${changes?renderTailorChanges(changes):(change?`<h4>Tailoring plan / change log</h4><pre class="jd">${esc(change)}</pre>`:'')}<h4>Tailored CV versions</h4><div>${j.cvVersions?.length?j.cvVersions.map(v=>`<div class="setting-row"><div class="meta"><b>${esc(v.version_label)}</b><small>${esc(v.original_filename)} · ${esc(v.created_at)}</small></div>${v.is_master?badge('MASTER','off'):badge('CHILD','teal')}</div>`).join(''):'<p class="muted">No job-specific CV yet.</p>'}</div>`;}
if(state.jobTab==='application'){
  const cvFiles=j.applicationCv?.files||[],formats=new Set(cvFiles.map(x=>String(x.format||'').toUpperCase())),gate=j.readyGate||{ok:false,reasons:[]},unresolved=gate.unresolvedConfirmationItems||[];
  const cvActions=j.applicationCv?'<button class="btn" data-job-action="open-tailored">'+(j.applicationCv.mode==='TAILORED'?'OPEN TAILORED CV':'OPEN REVIEW CV')+'</button>'+(formats.has('DOCX')?'<button class="btn" data-job-action="download-docx">DOWNLOAD DOCX</button>':'')+(formats.has('PDF')?'<button class="btn" data-job-action="download-pdf">DOWNLOAD PDF</button>':'')+(formats.has('MD')?'<button class="btn" data-job-action="preview-cv">PREVIEW</button>':''):'';
  const submittedAction=j.submittedCvAvailable?'<button class="btn primary" data-job-action="submitted-cv">OPEN SUBMITTED CV</button>':'';
  const noChangeAction=j.applicationCv?.mode==='NO_CHANGE_REVIEW'?'<button class="btn" data-job-action="approve-no-change">APPROVE EVIDENCE-SAFE NO-CHANGE</button>':'';
  body+='<div class="actions">'+cvActions+'<button class="btn" data-job-action="create-app">CREATE / OPEN PACKAGE</button><button class="btn" data-job-action="prepare-package">PREPARE LETTER + ANSWERS</button>'+noChangeAction+'<button class="btn primary" data-job-action="mark-applied">MARK APPLIED</button>'+submittedAction+'</div>'+
    '<div class="note" style="margin-top:12px"><b>'+esc(j.application?.status||'No package created yet')+'</b><br>Cover letter and application-answer drafts are grounded in the stored JD and CV evidence. JCC never submits an external application or marks it applied automatically.'+
    (gate.ok?'<br><b>READY gate:</b> PASS':'<br><b>READY gate:</b> '+esc((gate.reasons||[]).join(', ')||'not yet evaluated'))+
    ((gate.warnings||[]).length?'<br><b>Review warnings:</b> '+esc(gate.warnings.join(', ')):'')+
    (unresolved.length?'<br><b>User confirmation required:</b> '+esc(unresolved.join(', ')):'')+'</div>'+
    (art.coverLetter?'<h4>Cover letter</h4><pre class="jd">'+esc(art.coverLetter.content)+'</pre>':'')+
    (art.applicationAnswers?'<h4>Application answers</h4><pre class="jd">'+esc(art.applicationAnswers.content)+'</pre>':'');
}
if(state.jobTab==='contacts'){
  body+=(j.contacts?.length?simpleTable(j.contacts,['name','company','role','email','relationship']):'<p class="muted">No public contacts saved for this job.</p>')+
    '<div class="actions"><button class="btn" data-job-action="research-contacts">RESEARCH PUBLIC CONTACTS</button><button class="btn" data-job-action="add-contact">ADD CONFIRMED CONTACT</button><button class="btn" data-job-action="outreach">GENERATE OUTREACH DRAFTS</button></div>'+
    (art.outreach?'<h4>Outreach drafts</h4><pre class="jd">'+esc(art.outreach.content)+'</pre>':'');
}
if(state.jobTab==='interview'){
  const latestInterview=j.interviews?.[0],completeAction=latestInterview&&String(latestInterview.status||'').toUpperCase()!=='COMPLETED'?'<button class="btn" data-job-action="complete-interview">MARK INTERVIEW COMPLETED</button>':'';
  body+=(j.interviews?.length?simpleTable(j.interviews,['scheduled_at','stage','mode','interviewers','status']):'<p class="muted">No interview scheduled.</p>')+
    '<div class="actions"><button class="btn" data-job-action="add-interview">ADD INTERVIEW</button>'+completeAction+'<button class="btn primary" data-job-action="interview-prep">GENERATE INTERVIEW PREP</button></div>'+
    (art.interviewPrep?'<h4>Interview preparation</h4><pre class="jd">'+esc(art.interviewPrep.content)+'</pre>':'');
}
if(state.jobTab==='history')body+=j.history?.length?simpleTable(j.history,['created_at','old_status','new_status','actor','note']):'<p class="muted">No application history yet.</p>';openModal(`${j.title} · ${j.company}`,body,'',true)}

async function render(){if(!state.summary)await refreshBase();let html='';if(['dashboard','new','strong','good','ready','archived'].includes(state.route))html=state.route==='dashboard'?dashboard():jobsPage(state.route);else if(state.route==='queue')html=await queuePage();else if(['applications','followups','interviews','contacts'].includes(state.route))html=await listPage(state.route);else if(state.route==='history')html=await historyPage();else if(state.route==='profile')html=await profilePage();else if(state.route==='settings')html=await settingsPage();else if(state.route==='logs')html=await logsPage();else{location.hash='#dashboard';return}$('#view').innerHTML=html;bindView()}
function bindFilters(){$$('[data-filter]').forEach(el=>{el.value=state.filters[el.dataset.filter];el.onchange=()=>{state.filters[el.dataset.filter]=el.value;state.page=1;render()}});$('#clearfilters')?.addEventListener('click',()=>{state.filters={age:'any',role:'all',location:'all',match:'all',ats:'all',visa:'all',package:'all',q:state.filters.q};render()})}
function bindView(){bindFilters();$$('[data-route]').forEach(x=>x.onclick=()=>location.hash='#'+x.dataset.route);$$('[data-run-search]').forEach(x=>x.onclick=runSearch);$$('[data-page]').forEach(x=>x.onclick=()=>{state.page=Number(x.dataset.page);render()});$$('[data-view-job]').forEach(x=>x.onclick=()=>openJob(Number(x.dataset.viewJob)));$$('[data-open-queue-package]').forEach(x=>x.onclick=()=>openJob(Number(x.dataset.openQueuePackage),'application'));$$('[data-send-job]').forEach(x=>x.onclick=()=>sendJob(Number(x.dataset.sendJob)));$$('[data-override-job]').forEach(x=>x.onclick=()=>overrideJob(Number(x.dataset.overrideJob)));$$('[data-process-queue]').forEach(x=>x.onclick=()=>queueAction(x,'process'));$$('[data-review-queue]').forEach(x=>x.onclick=async()=>{try{await api(`/api/work-queue/${x.dataset.reviewQueue}/review`,jsonOpt('POST',{}));await openJob(Number(x.dataset.jobId),'application')}catch(e){toast(e.message,true)}});$$('[data-approve-queue]').forEach(x=>x.onclick=()=>queueAction(x,'approve'));$$('[data-retry-queue]').forEach(x=>x.onclick=()=>queueAction(x,'retry'));$$('[data-resolve-queue]').forEach(x=>x.onclick=()=>{state.settingsTab='applications';location.hash='#settings'});$$('[data-open-app]').forEach(x=>x.onclick=async()=>{try{const d=await api(`/api/jobs/${x.dataset.openApp}/open-application`);if(d.url)window.open(d.url,'_blank','noopener')}catch(e){toast(e.message,true)}});$$('[data-setting-tab]').forEach(x=>x.onclick=()=>{state.settingsTab=x.dataset.settingTab;render()});$('#saveapplicationfacts')?.addEventListener('click',saveApplicationFacts);$('#importcv')?.addEventListener('click',importCv);$$('[data-template-cv]').forEach(x=>x.onclick=()=>setTemplateCv(x.dataset.templateCv));$('#addrole')?.addEventListener('click',addRole);$$('[data-role-toggle]').forEach(x=>x.onchange=()=>toggleRole(x));$('#addlocation')?.addEventListener('click',addLocation);$$('[data-location-toggle]').forEach(x=>x.onchange=()=>toggleLocation(x));$('#addsource')?.addEventListener('click',addSource);$$('[data-source-toggle]').forEach(x=>x.onchange=()=>toggleSource(x));$$('[data-mode]').forEach(x=>x.onclick=()=>setMode(x.dataset.mode));$$('[data-jev-toggle]').forEach(x=>x.onclick=async()=>{await api('/api/jev/settings',jsonOpt('POST',{enabled:x.dataset.jevToggle==='1'}));render()});$('#openobsidian')?.addEventListener('click',openObsidian);$('#runbackup')?.addEventListener('click',runBackup);$('#rundoctor')?.addEventListener('click',runDoctor);$('#refreshlogs')?.addEventListener('click',render);$$('[data-run-detail]').forEach(x=>x.onclick=()=>runDetail(x.dataset.runDetail))}
async function queueAction(button,action){button.disabled=true;try{const id=button.dataset.processQueue||button.dataset.approveQueue||button.dataset.retryQueue,r=await api(`/api/work-queue/${id}/${action}`,jsonOpt('POST',{}));toast(`Queue: ${r.status}`);await refreshBase();render()}catch(e){toast(e.message,true);button.disabled=false}}
async function saveApplicationFacts(){try{const payload={};$$('[data-application-fact]').forEach(x=>payload[x.dataset.applicationFact]=x.value);await api('/api/profile/application-facts',jsonOpt('POST',payload));toast('Current application facts confirmed and saved');state.route='queue';location.hash='#queue';render()}catch(e){toast(e.message,true)}}
async function sendJob(id){try{const x=await api(`/api/jobs/${id}/send`,{method:'POST'});toast(x.status==='ALREADY_QUEUED'?'ALREADY QUEUED':'Queued for Work');await refreshBase();await render()}catch(e){toast(`SEND blocked: ${e.message}`,true)}}
async function overrideJob(id){const reason=prompt('Why do you want to override JCC’s match decision for this job?');if(reason===null)return;if(!reason.trim())return toast('Override reason is required',true);try{await api(`/api/jobs/${id}/override`,jsonOpt('POST',{reason:reason.trim()}));toast('Match decision overridden and recorded');await refreshBase();await render()}catch(e){toast(`OVERRIDE blocked: ${e.message}`,true)}}
async function deleteJobFromJcc(id){if(!confirm('Delete this job from JCC? It will be removed from your job lists and will not be rediscovered.'))return;try{await api(`/api/jobs/${id}`,{method:'DELETE'});toast('Job deleted and suppressed from rediscovery');if(state.jobModal?.id===id)closeModal();await refreshBase();await render()}catch(e){toast(`DELETE blocked: ${e.message}`,true)}}
async function importCv(){const f=$('#cvfile')?.files?.[0];if(!f)return toast('Choose a CV file first',true);try{await api(`/api/cv/import?filename=${encodeURIComponent(f.name)}`,{method:'POST',body:await f.arrayBuffer()});toast('New immutable master CV version imported');await refreshBase();render()}catch(e){toast(e.message,true)}}
async function setTemplateCv(id){try{await api('/api/cv/template',jsonOpt('POST',{cvVersionId:Number(id)}));toast('Formatting template selected independently from Master content');render()}catch(e){toast(e.message,true)}}
async function addRole(){try{await api('/api/roles',jsonOpt('POST',{family:$('#rolefamily').value,phrase:$('#rolephrase').value}));toast('Role saved');render()}catch(e){toast(e.message,true)}}
async function toggleRole(x){try{await api(`/api/roles/${x.dataset.roleToggle}`,jsonOpt('PATCH',{enabled:x.checked}));render()}catch(e){toast(e.message,true)}}
async function addLocation(){try{await api('/api/locations',jsonOpt('POST',{label:$('#locationlabel').value}));toast('Location normalized and saved');render()}catch(e){toast(e.message,true)}}
async function toggleLocation(x){try{await api(`/api/locations/${x.dataset.locationToggle}`,jsonOpt('PATCH',{enabled:x.checked}));render()}catch(e){toast(e.message,true)}}
async function addSource(){try{await api('/api/sources',jsonOpt('POST',{name:$('#sourcename').value,baseUrl:$('#sourceurl').value}));toast('Source onboarded');render()}catch(e){toast(e.message,true)}}
async function toggleSource(x){try{await api(`/api/sources/${x.dataset.sourceToggle}`,jsonOpt('PATCH',{enabled:x.checked}));render()}catch(e){toast(e.message,true)}}
async function setMode(mode){try{await api('/api/mode',jsonOpt('POST',{mode,everyHours:3,onStartup:false}));toast(`Discovery mode: ${mode}`);await refreshBase();render()}catch(e){toast(e.message,true)}}
async function openObsidian(){try{const x=await api('/api/knowledge/open');location.href=x.uri}catch(e){toast(e.message,true)}}
async function runBackup(){try{const x=await api('/api/system/backup',{method:'POST'});toast(`Backup created: ${x.path}`);render()}catch(e){toast(e.message,true)}}
async function runDoctor(){const o=$('#doctorout');o.innerHTML='<div class="empty"><div class="spinner"></div>Running full Doctor…</div>';try{const d=await api('/api/system/diagnostics');o.innerHTML=`<div class="diagnostics">${Object.entries(d.checks||{}).map(([k,v])=>`<div class="diag"><b>${esc(k)}</b>${badge(v.ok?'PASS':v.optional?'OPTIONAL':'FAIL',v.ok?'ok':v.optional?'warn':'err')}<small>${esc(v.version||v.error||'')}</small></div>`).join('')}</div>`}catch(e){o.innerHTML=`<div class="danger-note note">${esc(e.message)}</div>`}}
async function runDetail(id){const d=await api(`/api/discovery/runs/${id}`);openModal(`Discovery Run #${id}`,`<pre class="jd">${esc(JSON.stringify(d,null,2))}</pre>`,'',true)}
async function jobAction(action){
  const j=state.jobModal;if(!j)return;
  try{
    if(action==='send'){const x=await api('/api/jobs/'+j.id+'/send',{method:'POST'});toast(x.status==='ALREADY_QUEUED'?'ALREADY QUEUED':'Queued for Work')}
    else if(action==='override'){await overrideJob(j.id);state.jobModal=await api('/api/jobs/'+j.id);renderJobModal();return}
    else if(action==='open-application'){const x=await api('/api/jobs/'+j.id+'/open-application');if(x.url)window.open(x.url,'_blank','noopener')}
    else if(action==='delete'){await deleteJobFromJcc(j.id);return}
    else if(action==='rematch'){await api('/api/jobs/'+j.id+'/rematch',{method:'POST'});toast('Recruiter and ATS analysis refreshed')}
    else if(action==='reclean-jd'){const x=await api('/api/jobs/'+j.id+'/reclean-jd',{method:'POST'});toast(x.changed?'Stored raw JD re-cleaned into a new clean version':'Stored JD is already clean')}
    else if(action==='tailor'){toast('Tailoring CV…');const x=await api('/api/jobs/'+j.id+'/tailor',{method:'POST'});toast(x.status==='NO_MEANINGFUL_CHANGE'?(x.noChangeApprovalRequired?'No evidence-safe material change; the Master CV will be staged with a clear warning for your review.':'No new material change; the existing verified tailored CV remains available.'):'Tailored DOCX/PDF created, verified and rescored')}
    else if(action==='verify'){await api('/api/jobs/'+j.id+'/verify-tailored',{method:'POST'});toast('Post-tailor integrity verified')}
    else if(action==='open-tailored'){window.open('/api/jobs/'+j.id+'/application-cv','_blank','noopener')}
    else if(action==='download-docx'){window.location.href='/api/jobs/'+j.id+'/application-cv?format=DOCX&download=1'}
    else if(action==='download-pdf'){window.location.href='/api/jobs/'+j.id+'/application-cv?format=PDF&download=1'}
    else if(action==='preview-cv'){window.open('/api/jobs/'+j.id+'/application-cv?format=MD','_blank','noopener')}
    else if(action==='create-app'){await api('/api/jobs/'+j.id+'/application',{method:'POST'});toast('Application package created')}
    else if(action==='prepare-package'){await api('/api/jobs/'+j.id+'/prepare-package',jsonOpt('POST',{coverLetter:true,answers:true,outreach:true}));toast('Cover letter, application answers and unsent outreach draft prepared')}
    else if(action==='approve-no-change'){if(!confirm('Approve using the verified Master CV because no evidence-safe material tailoring change is available for this job?'))return;await api('/api/jobs/'+j.id+'/approve-no-change',jsonOpt('POST',{note:'Explicit user approval from application review UI'}));toast('Evidence-safe no-change explicitly approved')}
    else if(action==='ready'){if(!j.application)await api('/api/jobs/'+j.id+'/application',{method:'POST'});const fresh=await api('/api/jobs/'+j.id);await api('/api/applications/'+fresh.application.id+'/transition',jsonOpt('POST',{status:'READY_TO_APPLY'}));toast('Hard readiness gate passed; package is ready for manual application')}
    else if(action==='mark-applied'){
      const fresh=await api('/api/jobs/'+j.id);if(!fresh.application)throw new Error('Create the application package first');if(!fresh.applicationCv)throw new Error('No verified application CV is available');
      const files=fresh.applicationCv.files||[];if(!files.length)throw new Error('No physical CV file is registered');
      const label=f=>{const p=String(f.path||'').split(/[\\/]/);return p[p.length-1]||String(f.format||'CV')},choices=files.map((f,i)=>(i+1)+'. '+String(f.format||'FILE').toUpperCase()+' — '+label(f)+' — SHA-256 '+String(f.sha256||'not recorded')).join('\n');
      const raw=prompt('Which exact physical CV file did you manually submit?\n\n'+choices+'\n\nEnter the file number:');if(raw===null)return;const index=Number(raw)-1,chosen=files[index];if(!chosen)throw new Error('Select one of the listed physical CV files');
      if(!confirm('Confirm this is the exact file actually submitted:\n\n'+String(chosen.format||'FILE').toUpperCase()+' — '+label(chosen)+'\nSHA-256 '+String(chosen.sha256||'not recorded')))return;
      await api('/api/applications/'+fresh.application.id+'/mark-applied',jsonOpt('POST',{cvVersionId:fresh.applicationCv.cvVersionId,cvFileId:chosen.id||null}));toast('Applied recorded; exact submitted CV and application package archived immutably')
    }
    else if(action==='submitted-cv'){const fresh=await api('/api/jobs/'+j.id);if(!fresh.application||!fresh.submittedCvAvailable)throw new Error('No submitted CV exists yet');window.open('/api/applications/'+fresh.application.id+'/submitted-cv','_blank','noopener')}
    else if(action==='research-contacts'){const x=await api('/api/jobs/'+j.id+'/research-contacts',jsonOpt('POST',{}));toast(x.status==='NO_CONFIRMED_CONTACT'?'No confirmed public contact found; manual research remains available.':'Public contact candidates stored as unconfirmed until verified.')}
    else if(action==='outreach'){await api('/api/jobs/'+j.id+'/outreach',{method:'POST'});toast('Personalised outreach draft prepared; sending remains manual')}
    else if(action==='interview-prep'){await api('/api/jobs/'+j.id+'/interview-prep',{method:'POST'});toast('Interview prep generated from immutable submitted application artifacts')}
    else if(action==='add-contact'){const name=prompt('Confirmed contact name');if(!name)return;const role=prompt('Role / title')||'',sourceUrl=prompt('Public source URL (optional)')||'';await api('/api/jobs/'+j.id+'/contacts',jsonOpt('POST',{name,role,sourceUrl}));toast('User-confirmed contact saved')}
    else if(action==='add-interview'){const fresh=await api('/api/jobs/'+j.id);if(!fresh.application?.applied_at)throw new Error('Record the submitted application before adding an interview');const scheduledAt=prompt('Interview date/time (YYYY-MM-DD HH:MM)')||'',stage=prompt('Stage (e.g. Recruiter / Technical / Final)')||'';await api('/api/applications/'+fresh.application.id+'/interviews',jsonOpt('POST',{scheduledAt,stage}));toast('Interview linked to the submitted application')}
    else if(action==='complete-interview'){const fresh=await api('/api/jobs/'+j.id),interview=fresh.interviews?.[0];if(!interview)throw new Error('No interview event found');if(!confirm('Confirm this interview has actually been completed?'))return;await api('/api/interviews/'+interview.id+'/complete',jsonOpt('POST',{}));toast('Interview completion recorded as follow-up evidence')}
    state.jobModal=await api('/api/jobs/'+j.id);await refreshBase();renderJobModal();
  }catch(e){toast(e.message,true)}
}
async function saveImportedJob(){try{await api('/api/jobs/import',jsonOpt('POST',{company:$('#ijcompany').value,title:$('#ijtitle').value,location:$('#ijlocation').value,sourceUrl:$('#ijurl').value,jdRaw:$('#ijjd').value}));toast('Job imported and analysed');closeModal();await refreshBase();render()}catch(e){toast(e.message,true)}}
function globalBindings(){window.addEventListener('hashchange',route);$('#runbtn').onclick=runSearch;$('#cancelbtn').onclick=cancelSearch;$('#addbtn').onclick=()=>$('#addmenu').hidden=!$('#addmenu').hidden;$('#addmenu').onclick=e=>{const a=e.target.dataset.add;if(a==='job')importJobModal();if(a==='source'){state.settingsTab='sources';location.hash='#settings'}$('#addmenu').hidden=true};$('#profile-shortcut').onclick=()=>location.hash='#profile';$('#nav-toggle').onclick=()=>$('.sidebar').classList.toggle('open');$('#global-search').oninput=e=>{state.filters.q=e.target.value;state.page=1;if(['dashboard','new','strong','good','ready','archived'].includes(state.route))render()};document.addEventListener('click',e=>{if(e.target.closest('[data-close-modal]'))closeModal();const t=e.target.closest('[data-job-tab]');if(t){state.jobTab=t.dataset.jobTab;renderJobModal()}const a=e.target.closest('[data-job-action]');if(a)jobAction(a.dataset.jobAction);if(e.target.id==='saveimportjob')saveImportedJob()});}
function graphEvents(){try{const es=new EventSource('/api/knowledge-graph/events');es.onmessage=async()=>{try{state.graph=await api('/api/knowledge-graph');if(state.route==='dashboard')render()}catch{}}}catch{}}
function pollQueue(){clearInterval(state.queuePoll);state.queuePoll=setInterval(async()=>{if(state.route!=='queue')return;try{await refreshBase();await render()}catch{}},1000)}
document.addEventListener('click',e=>{const d=e.target.closest('[data-delete-job]');if(d)deleteJobFromJcc(Number(d.dataset.deleteJob))});
(async()=>{globalBindings();await refreshBase();route();graphEvents();pollQueue();if(state.summary?.scheduler?.running)pollDiscovery()})().catch(e=>{$('#view').innerHTML=`<div class="danger-note note"><b>JCC failed to load:</b> ${esc(e.message)}</div>`});
